function importNovel(){if(typeof diagnosticImportInteractionId!=='undefined')diagnosticImportInteractionId=typeof diagnosticInteractionId==='string'?diagnosticInteractionId:'';document.getElementById('novelFileInput').click();}
function uploadNovel(file){if(!file)return;var interactionId=typeof diagnosticImportInteractionId==='string'&&diagnosticImportInteractionId?diagnosticImportInteractionId:typeof diagnosticInteractionId==='string'?diagnosticInteractionId:'';if(typeof diagnosticImportInteractionId!=='undefined')diagnosticImportInteractionId='';saveReadingPosition();var name=file.name||'novel.txt';if(!/\.(txt|epub)$/i.test(name)){showToast('请选择 TXT 或 EPUB 文件');return;}showToast('正在导入《'+name.replace(/\.(txt|epub)$/i,'')+'》',4000);return file.arrayBuffer().then(function(buf){return api('/api/import',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-File-Name':encodeURIComponent(name)},body:buf,diagnosticInteractionId:interactionId});}).then(function(r){showToast('小说已导入');return loadLibrary(r.library,true);}).catch(showError).finally(function(){document.getElementById('novelFileInput').value='';});}

